import { useEffect, useRef, useState } from 'react'
import { Pause, Play } from 'lucide-react'
import { ruleSentenceParts } from '@/utils/alerts/describe'
import { radioGroupKeyDown } from '@/components/alerts/shared/alertShared'

// Which field a sentence token jumps to (D6: "each bold token jumps to its field").
const FIELD_FOR_PART = {
  metric: 'query', scope: 'query', condition: 'tiers', for: 'forSec', interval: 'intervalSec', notify: 'notify', repeat: 'repeatSec',
}

/**
 * The editor's head (D6): the rule as one sentence, generated by describe.js
 * from the draft as it stands, so a reviewer can read the whole rule without
 * opening a section, and every bold part jumps to its field. Beside it, the
 * status the rule will be saved with — production copies a paused status into
 * a clone and never shows it (R41) — and Cancel and Save.
 *
 * Save is never a dead grey button (R22). While something is missing it stays
 * focusable, says how many things are left, and pressing it lists them, each a
 * link to its field.
 */
export default function EditorHead({ view, status, onStatus, issues, onFocusField, onCancel, onSave, saving, mode }) {
  const [listOpen, setListOpen] = useState(false)
  const [asked, setAsked] = useState(0)
  const listRef = useRef(null)
  const blocked = issues.length > 0
  const parts = ruleSentenceParts(view)
  // The page is always told, so it can start showing what is missing beside
  // each field; when something is, the list opens and takes focus.
  const save = () => {
    onSave()
    if (blocked) {
      setListOpen(true)
      setAsked(n => n + 1)
    }
  }
  useEffect(() => {
    if (asked) listRef.current?.querySelector('button')?.focus()
  }, [asked])
  return (
    <div className="ae-head">
      <p className="ae-sentence" aria-live="polite">
        {parts.map((p, i) => {
          if (!FIELD_FOR_PART[p.field]) return <span key={i}>{p.text}</span>
          // A token's own spaces stay outside its button, which would drop them.
          const [, lead, core, trail] = /^(\s*)([\s\S]*?)(\s*)$/.exec(p.text)
          return (
            <span key={i}>
              {lead}
              <button type="button" className="ae-token" onClick={() => onFocusField(FIELD_FOR_PART[p.field])} title="Go to this field">{core}</button>
              {trail}
            </span>
          )
        })}
      </p>
      <div className="ae-head-actions">
        <div className="seg-toggle ae-status" role="radiogroup" aria-label="Save the rule as" onKeyDown={radioGroupKeyDown}>
          <button type="button" role="radio" aria-checked={status === 'ACTIVE'} className={`seg${status === 'ACTIVE' ? ' active' : ''}`} tabIndex={status === 'ACTIVE' ? 0 : -1} onClick={() => onStatus('ACTIVE')}>
            <Play aria-hidden="true" />Active
          </button>
          <button type="button" role="radio" aria-checked={status === 'PAUSED'} className={`seg${status === 'PAUSED' ? ' active' : ''}`} tabIndex={status === 'PAUSED' ? 0 : -1} onClick={() => onStatus('PAUSED')}>
            <Pause aria-hidden="true" />Paused
          </button>
        </div>
        <button type="button" className="hbtn" onClick={onCancel}>Cancel</button>
        <button
          type="button"
          className="hbtn primary ae-save"
          aria-disabled={blocked || saving}
          aria-describedby={blocked ? 'ae-issues-count' : undefined}
          onClick={saving ? undefined : save}
        >
          {mode === 'edit' ? 'Save changes' : 'Save rule'}
        </button>
        {blocked && <span id="ae-issues-count" className="ae-issues-count">{issues.length} to finish</span>}
      </div>
      {status === 'PAUSED' && (
        <p className="ae-paused-note">
          This rule will be saved paused: it won&apos;t be evaluated or notify anyone until it&apos;s resumed.
        </p>
      )}
      {blocked && listOpen && (
        <div className="ae-issues" ref={listRef} role="region" aria-label="What to finish before saving">
          <p className="ae-issues-title">Finish these to save the rule:</p>
          <ul>
            {issues.map((it, i) => (
              <li key={`${it.field}-${i}`}>
                <button type="button" className="ae-issue" onClick={() => onFocusField(it.field)}>{it.message}</button>
              </li>
            ))}
          </ul>
        </div>
      )}
    </div>
  )
}
